CREATE TYPE public.department AS ENUM ('marketing','communication','vigilance','support','sales');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.department NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.crm_role() RETURNS public.department LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE user_id=auth.uid() $$;
CREATE TABLE public.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference bigint GENERATED ALWAYS AS IDENTITY, name text NOT NULL, contact text NOT NULL, address text NOT NULL DEFAULT '', meeting_date date, meeting_time time, remark text NOT NULL DEFAULT '', stage public.department NOT NULL DEFAULT 'communication', audio_path text, audio_duration numeric, claimed_by uuid, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leads TO authenticated;
GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY department_lead_read ON public.leads FOR SELECT TO authenticated USING (public.crm_role() IS NOT NULL AND (public.crm_role()<>'sales' OR claimed_by=auth.uid()));
CREATE TABLE public.lead_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads(id), actor_id uuid, department public.department, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lead_events TO authenticated;
GRANT ALL ON public.lead_events TO service_role;
ALTER TABLE public.lead_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_read ON public.lead_events FOR SELECT TO authenticated USING (public.crm_role() IS NOT NULL AND (public.crm_role()<>'sales' OR EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND l.claimed_by=auth.uid())));
CREATE TABLE public.audio_sessions (user_id uuid NOT NULL, lead_id uuid NOT NULL REFERENCES public.leads(id), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, PRIMARY KEY(user_id,lead_id));
GRANT SELECT ON public.audio_sessions TO authenticated;
GRANT ALL ON public.audio_sessions TO service_role;
ALTER TABLE public.audio_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_audio ON public.audio_sessions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.crm_list() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.department:=public.crm_role(); BEGIN IF r IS NULL THEN RAISE EXCEPTION 'No department assigned to this account'; END IF; RETURN COALESCE((SELECT jsonb_agg(CASE WHEN r='sales' AND l.claimed_by IS DISTINCT FROM auth.uid() THEN jsonb_build_object('id',l.id,'reference',l.reference,'name','Protected lead','contact',NULL,'address',NULL,'meeting_date',NULL,'meeting_time',NULL,'remark',NULL,'stage',l.stage,'audio_path',l.audio_path,'audio_duration',l.audio_duration,'claimed_by',l.claimed_by,'created_at',l.created_at,'updated_at',l.updated_at) ELSE to_jsonb(l) END ORDER BY l.created_at DESC) FROM public.leads l WHERE r<>'sales' OR (l.stage='sales' AND (l.claimed_by IS NULL OR l.claimed_by=auth.uid()))),'[]'::jsonb); END $$;
CREATE FUNCTION public.crm_create(p_name text,p_contact text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; BEGIN IF public.crm_role() IS DISTINCT FROM 'marketing'::public.department THEN RAISE EXCEPTION 'Only Marketing can create leads'; END IF; IF length(trim(p_name))<2 OR length(regexp_replace(p_contact,'[^0-9]','','g'))<7 OR length(p_contact)>30 THEN RAISE EXCEPTION 'Enter a valid name and contact number'; END IF; INSERT INTO public.leads(name,contact,created_by) VALUES(trim(p_name),trim(p_contact),auth.uid()) RETURNING id INTO lid; INSERT INTO public.lead_events(lead_id,actor_id,department,action) VALUES(lid,auth.uid(),'marketing','Lead created and sent to Communication'); RETURN lid; END $$;
CREATE FUNCTION public.crm_advance(p_id uuid,p_name text DEFAULT NULL,p_address text DEFAULT NULL,p_date date DEFAULT NULL,p_time time DEFAULT NULL,p_remark text DEFAULT NULL,p_audio text DEFAULT NULL,p_duration numeric DEFAULT NULL,p_date_verified boolean DEFAULT false,p_time_verified boolean DEFAULT false,p_address_verified boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.department:=public.crm_role(); l public.leads; n public.department; BEGIN SELECT * INTO l FROM public.leads WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lead not found'; END IF; IF r IS NULL OR r<>l.stage OR l.claimed_by IS NOT NULL THEN RAISE EXCEPTION 'This lead is not in your department queue'; END IF;
IF r IN ('communication','vigilance') THEN IF length(trim(COALESCE(p_name,'')))<2 OR length(trim(COALESCE(p_address,'')))<5 OR p_date IS NULL OR p_time IS NULL THEN RAISE EXCEPTION 'Name, complete address, meeting date and time are required'; END IF;
IF r='vigilance' THEN IF p_audio IS NULL OR p_duration IS NULL OR p_duration<=0 THEN RAISE EXCEPTION 'A valid audio recording is mandatory'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='lead-audio' AND name=p_audio AND split_part(name,'/',1)=auth.uid()::text AND split_part(name,'/',2)=p_id::text) THEN RAISE EXCEPTION 'Upload the recording for this lead first'; END IF; END IF;
n:=CASE WHEN r='communication' THEN 'vigilance'::public.department ELSE 'support'::public.department END;
UPDATE public.leads SET name=trim(p_name),address=trim(p_address),meeting_date=p_date,meeting_time=p_time,remark=COALESCE(p_remark,''),audio_path=CASE WHEN r='vigilance' THEN p_audio ELSE audio_path END,audio_duration=CASE WHEN r='vigilance' THEN p_duration ELSE audio_duration END,stage=n,updated_at=now() WHERE id=p_id;
ELSIF r='support' THEN IF NOT (p_date_verified AND p_time_verified AND p_address_verified) OR l.meeting_date IS NULL OR l.meeting_time IS NULL OR length(l.address)<5 THEN RAISE EXCEPTION 'Verify date, time and complete address before allocation'; END IF; n:='sales'; UPDATE public.leads SET stage=n,updated_at=now() WHERE id=p_id;
ELSE RAISE EXCEPTION 'Action not allowed'; END IF;
INSERT INTO public.lead_events(lead_id,actor_id,department,action) VALUES(p_id,auth.uid(),r,CASE r WHEN 'communication' THEN 'Meeting scheduled · sent to Vigilance' WHEN 'vigilance' THEN 'Audio verified · sent to Support' ELSE 'Lead allocated to Sales' END); END $$;
CREATE FUNCTION public.crm_audio(p_id uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.leads; s public.audio_sessions; BEGIN IF public.crm_role() IS DISTINCT FROM 'sales'::public.department THEN RAISE EXCEPTION 'Only Sales can claim'; END IF; SELECT * INTO l FROM public.leads WHERE id=p_id AND stage='sales' AND (claimed_by IS NULL OR claimed_by=auth.uid()); IF NOT FOUND OR l.audio_duration IS NULL OR l.audio_duration<=0 THEN RAISE EXCEPTION 'Recording unavailable'; END IF; IF p_action='start' THEN INSERT INTO public.audio_sessions(user_id,lead_id,started_at) VALUES(auth.uid(),p_id,now()) ON CONFLICT(user_id,lead_id) DO UPDATE SET started_at=now(),completed_at=NULL;
ELSIF p_action='complete' THEN SELECT * INTO s FROM public.audio_sessions WHERE user_id=auth.uid() AND lead_id=p_id; IF NOT FOUND OR extract(epoch FROM now()-s.started_at)<l.audio_duration THEN RAISE EXCEPTION 'Listen to the complete recording before claiming'; END IF; UPDATE public.audio_sessions SET completed_at=now() WHERE user_id=auth.uid() AND lead_id=p_id;
ELSIF p_action='claim' THEN SELECT * INTO s FROM public.audio_sessions WHERE user_id=auth.uid() AND lead_id=p_id; IF NOT FOUND OR s.completed_at IS NULL THEN RAISE EXCEPTION 'Listen to the complete recording before claiming'; END IF; UPDATE public.leads SET claimed_by=auth.uid(),updated_at=now() WHERE id=p_id AND claimed_by IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'This lead has already been claimed'; END IF; INSERT INTO public.lead_events(lead_id,actor_id,department,action) VALUES(p_id,auth.uid(),'sales','Lead claimed by Sales'); ELSE RAISE EXCEPTION 'Invalid action'; END IF; END $$;
REVOKE ALL ON FUNCTION public.crm_role(), public.crm_list(), public.crm_create(text,text), public.crm_advance(uuid,text,text,date,time,text,text,numeric,boolean,boolean,boolean), public.crm_audio(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_role(), public.crm_list(), public.crm_create(text,text), public.crm_advance(uuid,text,text,date,time,text,text,numeric,boolean,boolean,boolean), public.crm_audio(uuid,text) TO authenticated;
CREATE POLICY upload_vigilance_audio ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='lead-audio' AND public.crm_role()='vigilance' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.leads WHERE id::text=(storage.foldername(name))[2] AND stage='vigilance'));
CREATE POLICY read_department_audio ON storage.objects FOR SELECT TO authenticated USING(bucket_id='lead-audio' AND public.crm_role() IS NOT NULL AND EXISTS(SELECT 1 FROM public.leads WHERE audio_path=name AND (public.crm_role()<>'sales' OR (stage='sales' AND (claimed_by IS NULL OR claimed_by=auth.uid())))));
